PROHIBITED_LINE_START = frozenset(
    "ã€ï¼Œã€‚ï¼Žï¼šï¼›ï¼ï¼Ÿâ€¼â‡âˆâ‰â€™â€ï¼‰ã€•ã€‘ã€—ã€™ã€›ï¼½ï½ã€‰ã€‹ã€ã€ã€…Â·ãƒ»â€”â¸ºâ€¥â€¦ï½žï¼,.!?;:/)]}>'\"%"
)
PROHIBITED_LINE_END = frozenset("â€˜â€œï¼ˆã€”ã€ã€–ã€˜ã€šï¼»ï½›ã€ˆã€Šã€Œã€Žï¼([<{/\"'")
UNBREAKABLE_PUNCTUATION_PAIRS = frozenset({"â€”â€”", "â€¦â€¦"})


def _with_font_snapshot(method):
    @wraps(method)
    def wrapped(self, *args, **kwargs):
        bundle = self._font_bundle
        if bundle is None:
            raise RuntimeError("å­—ä½“å°šæœªå‡†å¤‡å®Œæˆ")
        previous = getattr(self._render_font_state, "bundle", None)
        self._render_font_state.bundle = bundle
        try:
            return method(self, *args, **kwargs)
        finally:
            if previous is None:
                del self._render_font_state.bundle
            else:
                self._render_font_state.bundle = previous

    return wrapped


